-- Sourced identity catalogue. Inclusion does not publish a clinical review or self-treatment protocol.
CREATE TABLE IF NOT EXISTS ilb_ehr_catalogue (
 practice_code VARCHAR(64) PRIMARY KEY,
 category_name VARCHAR(120) NOT NULL,
 record_kind ENUM('MODALITY','BRANCH','FAMILY','DELIVERY_STYLE') NOT NULL,
 scope_status ENUM('CORE','RELATED') NOT NULL,
 parent_practice_code VARCHAR(64) NULL,
 aliases_text TEXT NOT NULL,
 overview_text TEXT NOT NULL,
 source_url TEXT NOT NULL,
 source_name VARCHAR(255) NOT NULL,
 source_checked_on DATE NOT NULL,
 publication_status ENUM('DRAFT','PUBLISHED','ARCHIVED') NOT NULL DEFAULT 'DRAFT',
 FOREIGN KEY(practice_code) REFERENCES ilb_ehr_practice(practice_code),
 FOREIGN KEY(parent_practice_code) REFERENCES ilb_ehr_practice(practice_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
START TRANSACTION;
ON DUPLICATE KEY UPDATE practice_name=VALUES(practice_name);
ON DUPLICATE KEY UPDATE category_name=VALUES(category_name),record_kind=VALUES(record_kind),scope_status=VALUES(scope_status),parent_practice_code=VALUES(parent_practice_code),aliases_text=VALUES(aliases_text),overview_text=VALUES(overview_text),source_url=VALUES(source_url),source_name=VALUES(source_name),source_checked_on=VALUES(source_checked_on);
ON DUPLICATE KEY UPDATE practice_name=VALUES(practice_name);
ON DUPLICATE KEY UPDATE overview_text=VALUES(overview_text),source_url=VALUES(source_url),source_name=VALUES(source_name),source_checked_on=VALUES(source_checked_on);
COMMIT;
